CREATE TYPE "RoleAssignmentStatus" AS ENUM ('DRAFT','PENDING_REVIEW','ACTIVE','REJECTED','SUSPENDED','ARCHIVED');
CREATE TYPE "CredentialVerificationStatus" AS ENUM ('UNVERIFIED','PENDING','DOCUMENT_VERIFIED','VERIFIED','REJECTED','EXPIRED');
CREATE TYPE "ActivationRequestStatus" AS ENUM ('DRAFT','SUBMITTED','UNDER_REVIEW','MORE_INFORMATION_REQUIRED','RESUBMITTED','APPROVED','REJECTED','SUSPENDED','ARCHIVED');
CREATE TABLE "ProfessionalProfile" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"personId" UUID UNIQUE NOT NULL REFERENCES "Person"("id") ON DELETE RESTRICT,"headline" TEXT,"bio" TEXT,"regionCode" TEXT,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "RoleAssignment" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"accountId" UUID NOT NULL REFERENCES "Account"("id") ON DELETE RESTRICT,"role" TEXT NOT NULL,"status" "RoleAssignmentStatus" NOT NULL DEFAULT 'DRAFT',"scope" JSONB,"activeAt" TIMESTAMPTZ,"endedAt" TIMESTAMPTZ,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE("accountId","role"));
CREATE TABLE "Credential" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"personId" UUID NOT NULL REFERENCES "Person"("id") ON DELETE RESTRICT,"issuer" TEXT NOT NULL,"title" TEXT NOT NULL,"credentialNumber" TEXT,"issuedAt" TIMESTAMPTZ,"expiresAt" TIMESTAMPTZ,"verificationStatus" "CredentialVerificationStatus" NOT NULL DEFAULT 'UNVERIFIED',"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "Document" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"credentialId" UUID REFERENCES "Credential"("id") ON DELETE RESTRICT,"ownerId" UUID NOT NULL,"storageKey" TEXT NOT NULL UNIQUE,"originalName" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"byteSize" INTEGER NOT NULL,"sha256" TEXT NOT NULL UNIQUE,"status" TEXT NOT NULL DEFAULT 'UPLOADED',"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"archivedAt" TIMESTAMPTZ);
CREATE TABLE "ActivationRequest" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"applicantId" UUID NOT NULL REFERENCES "Account"("id") ON DELETE RESTRICT,"roleAssignmentId" UUID NOT NULL REFERENCES "RoleAssignment"("id") ON DELETE RESTRICT,"status" "ActivationRequestStatus" NOT NULL DEFAULT 'DRAFT',"submittedAt" TIMESTAMPTZ,"decidedAt" TIMESTAMPTZ,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "ReviewDecision" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"activationRequestId" UUID NOT NULL REFERENCES "ActivationRequest"("id") ON DELETE RESTRICT,"reviewerId" UUID NOT NULL REFERENCES "Account"("id") ON DELETE RESTRICT,"outcome" TEXT NOT NULL,"reason" TEXT,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "Notification" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"accountId" UUID NOT NULL REFERENCES "Account"("id") ON DELETE RESTRICT,"type" TEXT NOT NULL,"payload" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"sentAt" TIMESTAMPTZ,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "AuditEvent" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"actorId" UUID REFERENCES "Person"("id") ON DELETE RESTRICT,"action" TEXT NOT NULL,"resource" TEXT NOT NULL,"resourceId" TEXT,"requestId" TEXT,"ipAddress" TEXT,"metadata" JSONB,"occurredAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX "ActivationRequest_status_createdAt_idx" ON "ActivationRequest" ("status","createdAt");
CREATE INDEX "AuditEvent_resource_resourceId_occurredAt_idx" ON "AuditEvent" ("resource","resourceId","occurredAt");